import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";var i=JSON.parse(`{"title":"Insecure storage of session tokens","description":"","frontmatter":{"search":{"exclude":true}},"headers":[],"relativePath":"d/web/insecure-storage-of-session-tokens.md","filePath":"d/web/insecure-storage-of-session-tokens.md","lastUpdated":1781102819000}`),a={name:`d/web/insecure-storage-of-session-tokens.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /d/web/insecure-storage-of-session-tokens.md for this page in Markdown format</div><h1 id="insecure-storage-of-session-tokens" tabindex="-1">Insecure storage of session tokens <a class="header-anchor" href="#insecure-storage-of-session-tokens" aria-label="Permalink to “Insecure storage of session tokens”">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to “Description”">​</a></h2><p>Web browsers have security mechanims for protecting session tokens. Those mechanisms prevent access to the session token via JavaScript and ensuring that the session token is always sent via encrypted channels. They are however only applicable to Cookies.</p><p>Web applications storing session tokens in the browser&#39;s session session storage, local storage or IndexDB make the session tokens readable via JavaScript. If tokens are stored in the local storage or IndexDB (instead of the session storage), the data is retained after the browser is closed. This further increases the risk because the tokens are retained even after the browser is closed.</p><p>Single-page apps (SPAs) require access tokens to call APIs. They often also have a refresh token that allows offline access to the users&#39; resources. This refresh token can request new access tokens without user interaction and are a particularly interesting target in cross-site scripting (XSS) attacks.</p><p>If tokens with wide scopes are issued to the SPA, this can potentially give an attacker access to functionality not normally accessible through the user interface. In the event of theft, an attacker can at least take over the identity of the victim and perform actions.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to “Recommendation”">​</a></h2><p>We advise against storing sensitive data such as session tokens in the session storage, local storage, or the IndexDB of the web browser.</p><ul><li>Prefer cookies with <code>Secure</code> and <code>HttpOnly</code> flags over other storage mechanisms.</li><li>If this is not possible, consider setting the refresh token as a cookie.</li><li>Prefer session storage over local storage and IndexDB.</li><li>Consider a Backend-for-Frontend architecture. <sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> <sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup> <sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></li></ul><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p><a href="https://learn.microsoft.com/en-us/azure/architecture/guide/web/secure-single-page-application-authorization" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/azure/architecture/guide/web/secure-single-page-application-authorization</a> <a href="#fnref1" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p><a href="https://curity.io/resources/learn/the-token-handler-pattern/" target="_blank" rel="noreferrer">https://curity.io/resources/learn/the-token-handler-pattern/</a> <a href="#fnref2" class="footnote-backref">↩︎</a></p></li><li id="fn3" class="footnote-item"><p><a href="https://damienbod.com/2022/01/10/comparing-the-backend-for-frontend-bff-security-architecture-with-an-spa-ui-using-a-public-api/" target="_blank" rel="noreferrer">https://damienbod.com/2022/01/10/comparing-the-backend-for-frontend-bff-security-architecture-with-an-spa-ui-using-a-public-api/</a> <a href="#fnref3" class="footnote-backref">↩︎</a></p></li></ol></section><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><a href="#fnref1" class="footnote-backref">↩︎</a></li><li id="fn2" class="footnote-item"><a href="#fnref2" class="footnote-backref">↩︎</a></li><li id="fn3" class="footnote-item"><a href="#fnref3" class="footnote-backref">↩︎</a></li></ol></section>`,14)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};